workspace_cargo_toml.raw_excerpt:
[workspace]
members = ["crates/*"]
exclude = [
  "scripts",
  # Needs nightly
  "crates/uv-trampoline",
]
resolver = "2"

[workspace.package]
edition = "2024"
rust-version = "1.93.0"
homepage = "https://pypi.org/project/uv/"
repository = "https://github.com/astral-sh/uv"
authors = ["uv"]
license = "MIT OR Apache-2.0"

[workspace.dependencies]
uv-audit = { version = "0.0.47", path = "crates/uv-audit" }
uv-auth = { version = "0.0.47", path = "crates/uv-auth" }
uv-bin-install = { version = "0.0.47", path = "crates/uv-bin-install" }
uv-build-backend = { version = "0.0.47", path = "crates/uv-build-backend" }
uv-build-frontend = { version = "0.0.47", path = "crates/uv-build-frontend" }
uv-cache = { version = "0.0.47", path = "crates/uv-cache" }
uv-cache-info = { version = "0.0.47", path = "crates/uv-cache-info" }
uv-cache-key = { version = "0.0.47", path = "crates/uv-cache-key" }
uv-cli = { version = "0.0.47", path = "crates/uv-cli" }
uv-client = { version = "0.0.47", path = "crates/uv-client" }
uv-configuration = { version = "0.0.47", path = "crates/uv-configuration" }
uv-console = { version = "0.0.47", path = "crates/uv-console" }
uv-dirs = { version = "0.0.47", path = "crates/uv-dirs" }
uv-dispatch = { version = "0.0.47", path = "crates/uv-dispatch" }
uv-distribution = { version = "0.0.47", path = "crates/uv-distribution" }
uv-distribution-filename = { version = "0.0.47", path = "crates/uv-distribution-filename" }
uv-distribution-types = { version = "0.0.47", path = "crates/uv-distribution-types" }
uv-extract = { version = "0.0.47", path = "crates/uv-extract" }
uv-fastid = { version = "0.0.47", path = "crates/uv-fastid" }
uv-flags = { version = "0.0.47", path = "crates/uv-flags" }
uv-fs = { version = "0.0.47", path = "crates/uv-fs", features = [
  "serde",
  "tokio",
] }
uv-git = { version = "0.0.47", path = "crates/uv-git" }
uv-git-types = { version = "0.0.47", path = "crates/uv-git-types" }
uv-globfilter = { version = "0.0.47", path = "crates/uv-globfilter" }
uv-install-wheel = { version = "0.0.47", path = "crates/uv-install-wheel", default-features = false }
uv-installer = { version = "0.0.47", path = "crates/uv-installer" }
uv-keyring = { version = "0.0.47", path = "crates/uv-keyring" }
uv-logging = { version = "0.0.47", path = "crates/uv-logging" }
uv-macros = { version = "0.0.47", path = "crates/uv-macros" }
uv-metadata = { version = "0.0.47", path = "crates/uv-metadata" }
uv-netrc = { version = "0.0.47", path = "crates/uv-netrc" }
uv-normalize = { version = "0.0.47", path = "crates/uv-normalize" }
uv-once-map = { version = "0.0.47", path = "crates/uv-once-map" }
uv-options-metadata = { version = "0.0.47", path = "crates/uv-options-metadata" }
uv-performance-memory-allocator = { version = "0.0.47", path = "crates/uv-performance-memory-allocator" }
uv-pep440 = { version = "0.0.47", path = "crates/uv-pep440", features = [
  "tracing",
